INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38961, 'Jeremiah 51:43', 'Jeremiah', 51, 43, 'د هغۀ ښارونه به وران او تباه کړى او په اوچه دشته او ميره باندې به بدل شى، هغه به په داسې زمکه باندې بدل شى چې څوک به هم په کښې نۀ اوسيږى، او نۀ به څوک په کښې سفر کوى.', 'د هغۀ شارونه به وران او تباه کری او په اوچه دشته او میره باندې به بدل شی، هغه به په داسې زمکه باندې بدل شی چې چوک به هم په کشې نۀ اوسیزی، او نۀ به چوک په کشې سفر کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_43.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38962, 'Jeremiah 51:44', 'Jeremiah', 51, 44, 'زۀ به د بابل معبود بيل بُت ته سزا ورکړم، او څۀ چې يې خوړلى دى هغه به پرې ګنډير کړم. قومونه به نور د هغۀ عبادت نۀ کوى. او د بابل دېوالونه به راوغورزيږى.', 'زۀ به د بابل معبود بیل بت ته سزا ورکرم، او چۀ چې یې خورلی دی هغه به پرې ګندیر کرم. قومونه به نور د هغۀ عبادت نۀ کوی. او د بابل دېوالونه به راوغورزیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_44.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38963, 'Jeremiah 51:45', 'Jeremiah', 51, 45, 'اے زما خلقو د هغۀ نه رابهر شئ. د خپل ژوند د بچ کولو دپاره د هغه ځائ نه منډه کړئ. او د مالِک خُدائ د سخت غضب نه وتښتئ.', 'اے زما خلقو د هغۀ نه رابهر شی. د خپل ژوند د بچ کولو دپاره د هغه جای نه منده کری. او د مالک خدای د سخت غضب نه وتشتی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_45.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38964, 'Jeremiah 51:46', 'Jeremiah', 51, 46, 'تاسو چې په دغه مُلک کومې افواه ګانې اورئ نو چې د هغې په وجه نۀ بې‌زړۀ شئ او نۀ ويرېږئ. دا افواه به کال په کال راځى. ظلم او فساد به مُلک کښې راوچت شى او بادشاهان به د يو بل سره جنګونه کوى.', 'تاسو چې په دغه ملک کومې افواه ګانې اوری نو چې د هغې په وجه نۀ بې‌زرۀ شی او نۀ ویرېزی. دا افواه به کال په کال راجی. ظلم او فساد به ملک کشې راوچت شی او بادشاهان به د یو بل سره جنګونه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_46.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38965, 'Jeremiah 51:47', 'Jeremiah', 51, 47, 'خو په حقيقت کښې هغه وخت راروان دے چې زۀ به د بابليانو بُتانو ته سزا ورکړم، او د هغۀ ټول مُلک به وشرميږى، او د هغوئ قتل شوى کسان به ټول په کښې مړۀ پراتۀ وى.', 'خو په حقیقت کشې هغه وخت راروان دے چې زۀ به د بابلیانو بتانو ته سزا ورکرم، او د هغۀ تول ملک به وشرمیزی، او د هغوی قتل شوی کسان به تول په کشې مرۀ پراتۀ وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_47.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38966, 'Jeremiah 51:48', 'Jeremiah', 51, 48, 'نو بيا به آسمان او زمکه او هر څۀ چې په کښې دى د بابل په شکست د خوشحالۍ چغې ووهى، ځکه چې د شمال نه به تباه کوونکى فوجيان په هغۀ حمله وکړى، دا د مالِک خُدائ فرمان دے.', 'نو بیا به اسمان او زمکه او هر چۀ چې په کشې دی د بابل په شکست د خوشحالی چغې ووهی، جکه چې د شمال نه به تباه کوونکی فوجیان په هغۀ حمله وکری، دا د مالک خدای فرمان دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_48.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38967, 'Jeremiah 51:49', 'Jeremiah', 51, 49, 'لکه څنګه چې بابل د بنى اِسرائيلو او د ټولې دُنيا د قتل عام سبب جوړ شوے وو، نو بيا به هغه هم هغه شان قتل کړے شى.“', 'لکه چنګه چې بابل د بنی اسراییلو او د تولې دنیا د قتل عام سبب جور شوے وو، نو بیا به هغه هم هغه شان قتل کرے شی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_49.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38968, 'Jeremiah 51:50', 'Jeremiah', 51, 50, '”تاسو څوک چې د مرګ نه راتښتېدلى يئ، ودرېږئ مه، لاړ شئ. تاسو چې څومره هم لرې يئ نو مالِک خُدائ يادوئ. او د خپل کور يروشلم په حقله سوچ کوئ.“', '”تاسو چوک چې د مرګ نه راتشتېدلی یی، ودرېزی مه، لار شی. تاسو چې چومره هم لرې یی نو مالک خدای یادوی. او د خپل کور یروشلم په حقله سوچ کوی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_50.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38969, 'Jeremiah 51:51', 'Jeremiah', 51, 51, 'تاسو وايئ چې، ”مونږ په شرمونو وشرمېدو، او زمونږ بې‌عزتى وشوه او شرم مو په مخ راخور شوے دے، ځکه چې غېر مُلکيان د مالِک خُدائ په مقدس ځائ کښې راداخل شوى دى.“', 'تاسو وایی چې، ”مونز په شرمونو وشرمېدو، او زمونز بې‌عزتی وشوه او شرم مو په مخ راخور شوے دے، جکه چې غېر ملکیان د مالک خدای په مقدس جای کشې راداخل شوی دی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_51.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38970, 'Jeremiah 51:52', 'Jeremiah', 51, 52, 'مالِک خُدائ فرمائى چې، ”هغه ورځې راروانې دى کله چې به زۀ د بابل بُتانو ته سزا ورکړم نو د هغوئ د زخمونو زبيرګى به ټول مُلک کښې اورېدلے شى.', 'مالک خدای فرمایی چې، ”هغه ورجې راروانې دی کله چې به زۀ د بابل بتانو ته سزا ورکرم نو د هغوی د زخمونو زبیرګی به تول ملک کشې اورېدلے شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_52.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38971, 'Jeremiah 51:53', 'Jeremiah', 51, 53, 'کۀ بابليان آسمان ته هم وخېژى او هلته يوه مضبوطه قلعه جوړه کړى، نو زۀ به هلته هم دشمنان ورولېږم چې هغوئ چور کړى، مالِک خُدائ فرمائى.“', 'کۀ بابلیان اسمان ته هم وخېژی او هلته یوه مضبوطه قلعه جوره کری، نو زۀ به هلته هم دشمنان ورولېزم چې هغوی چور کری، مالک خدای فرمایی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_53.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38972, 'Jeremiah 51:54', 'Jeremiah', 51, 54, '”د ژړا آوازونه د بابل نه راځى، د لوئ تباهۍ آوازونه د بابليانو د زمکې نه اورېدلے کيږى.', '”د ژرا اوازونه د بابل نه راجی، د لوی تباهی اوازونه د بابلیانو د زمکې نه اورېدلے کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_54.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38973, 'Jeremiah 51:55', 'Jeremiah', 51, 55, 'مالِک خُدائ به بابل تباه کړى، او هغه به د هغوئ د شور نه ډک ښار خاموشه کړى، دشمن به لکه د اوبو د غضبناکو چپو په شان راروان وى او د هغوئ د آوازونو شور به اورېدلے شى.', 'مالک خدای به بابل تباه کری، او هغه به د هغوی د شور نه دک شار خاموشه کری، دشمن به لکه د اوبو د غضبناکو چپو په شان راروان وی او د هغوی د اوازونو شور به اورېدلے شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_55.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38974, 'Jeremiah 51:56', 'Jeremiah', 51, 56, 'تباه کوونکے به د بابل خلاف راشى، د هغوئ جنګى فوجيان به ونيولے شى او د هغوئ ليندې به ماتې کړے شى. ځکه چې مالِک خُدائ د انتقام اخستلو خُدائ پاک دے او هغه به پوره بدله ورکړى.', 'تباه کوونکے به د بابل خلاف راشی، د هغوی جنګی فوجیان به ونیولے شی او د هغوی لیندې به ماتې کرے شی. جکه چې مالک خدای د انتقام اخستلو خدای پاک دے او هغه به پوره بدله ورکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_56.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38975, 'Jeremiah 51:57', 'Jeremiah', 51, 57, 'زۀ به د هغۀ مشران او پوهان نشه کړم، د هغۀ حکمرانان، آفسران، او فوجيان به هم نشه کړم. هغوئ به د تل دپاره اودۀ شى او بيا به نۀ راپاڅى، دا د بادشاه فرمان دے د چا نوم چې مالِک خُدائ ربُ الافواج دے.“', 'زۀ به د هغۀ مشران او پوهان نشه کرم، د هغۀ حکمرانان، افسران، او فوجیان به هم نشه کرم. هغوی به د تل دپاره اودۀ شی او بیا به نۀ راپاچی، دا د بادشاه فرمان دے د چا نوم چې مالک خدای رب الافواج دے.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_57.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38976, 'Jeremiah 51:58', 'Jeremiah', 51, 58, 'مالِک خُدائ ربُ الافواج داسې فرمائى چې، ”د بابل پيړ دېوالونه به هوار کړے شى او د هغۀ اوچتې دروازې به وسوزولے شى، نو خلقو يې خپل ځان ستړے کړو خو هيڅ فائده يې ونۀ کړه، د دې قوم ټول محنت صرف د اور دپاره خشاک دے.“', 'مالک خدای رب الافواج داسې فرمایی چې، ”د بابل پیر دېوالونه به هوار کرے شی او د هغۀ اوچتې دروازې به وسوزولے شی، نو خلقو یې خپل جان سترے کرو خو هیچ فایده یې ونۀ کره، د دې قوم تول محنت صرف د اور دپاره خشاک دے.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_58.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38977, 'Jeremiah 51:59', 'Jeremiah', 51, 59, 'يرمياه نبى دا پېغام د عملى آفسر سراياه د نيرياه زوئ يعنې د محسياه نمسې ته هغه وخت ورکړو کله چې هغه بابل ته د صدقياه د يهوداه بادشاه د حکومت په څلورم کال د هغۀ سره لاړو.', 'یرمیاه نبی دا پېغام د عملی افسر سرایاه د نیریاه زوی یعنې د محسیاه نمسې ته هغه وخت ورکرو کله چې هغه بابل ته د صدقیاه د یهوداه بادشاه د حکومت په چلورم کال د هغۀ سره لارو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_59.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38978, 'Jeremiah 51:60', 'Jeremiah', 51, 60, 'يرمياه د هغه ټولو افتونو د تفصيل په حقله چې په بابل باندې راتلونکى وُو په يو طومار کښې وليکل.', 'یرمیاه د هغه تولو افتونو د تفصیل په حقله چې په بابل باندې راتلونکی وو په یو طومار کشې ولیکل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_60.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38979, 'Jeremiah 51:61', 'Jeremiah', 51, 61, 'هغۀ سراياه ته وفرمائيل، ”کله چې تۀ بابل ته ورسېږې نو تۀ دا ټول کلام په اوچت آواز سره خلقو ته ولوله.', 'هغۀ سرایاه ته وفرماییل، ”کله چې تۀ بابل ته ورسېزې نو تۀ دا تول کلام په اوچت اواز سره خلقو ته ولوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_61.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(38980, 'Jeremiah 51:62', 'Jeremiah', 51, 62, 'نو بيا داسې وايه چې، اے مالِکه خُدايه، تا وفرمائيل چې تاسو به دا ځائ تباه کړئ، نو په دې کښې به نۀ انسان او نۀ ځناور اوسيږى، او دا به د تل دپاره وران ويجاړ پروت وى.', 'نو بیا داسې وایه چې، اے مالکه خدایه، تا وفرماییل چې تاسو به دا جای تباه کری، نو په دې کشې به نۀ انسان او نۀ جناور اوسیزی، او دا به د تل دپاره وران ویجار پروت وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_62.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38981, 'Jeremiah 51:63', 'Jeremiah', 51, 63, 'کله چې تۀ د دې طومار لوستل بند کړې، نو يو کاڼے ورپورې وتړه او د فرات د سيند په مينځ کښې يې وغورزوه.', 'کله چې تۀ د دې طومار لوستل بند کرې، نو یو کانے ورپورې وتره او د فرات د سیند په مینج کشې یې وغورزوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_63.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(38982, 'Jeremiah 51:64', 'Jeremiah', 51, 64, 'نو بيا هغوئ ته ووايه چې، دغه شان به بابليان ډوب شى او هيڅکله به بيا راوچت نۀ شى د هغه افت په وجه کوم چې زۀ په دوئ نازلوم. نو د هغۀ خلق به راوغورزيږى.“ د يرمياه خبرې دلته په دې ځائ باندې ختمې شوې.', 'نو بیا هغوی ته ووایه چې، دغه شان به بابلیان دوب شی او هیچکله به بیا راوچت نۀ شی د هغه افت په وجه کوم چې زۀ په دوی نازلوم. نو د هغۀ خلق به راوغورزیزی.“ د یرمیاه خبرې دلته په دې جای باندې ختمې شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_51_64.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
