(39035, 'Leviticus 7:12', 'Leviticus', 7, 12, 'که چېرې هغه کس دا نذرانه خدای ته د شکرانې د نذرانې په توګه وړاندې کوي، هغه به د هغه حیوان سره چې قرباني کیږي، د یوې فطیرې ډوډۍ نذرانه وړاندې کوي: هغه دې د ښو اوړو څخه درې ډوله ډوډۍ پخې کړي چې دوه یې د زیتونو په تېلو کې پخې شوې وي او یوه دې نرۍ ډوډۍ وي چې تېل ورباندې موښل شوي وي.', 'که چېرې هغه کس دا نذرانه خدای ته د شکرانې د نذرانې په توګه وراندې کوی، هغه به د هغه حیوان سره چې قربانی کیزی، د یوې فطیرې دودی نذرانه وراندې کوی: هغه دې د شو اورو چخه درې دوله دودی پخې کری چې دوه یې د زیتونو په تېلو کې پخې شوې وی او یوه دې نری دودی وی چې تېل ورباندې موشل شوی وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_7_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39036, 'Leviticus 7:13', 'Leviticus', 7, 13, 'هغه کس دې څو خمیره ډوډۍ هم وړاندې کړي.', 'هغه کس دې چو خمیره دودی هم وراندې کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_7_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(39037, 'Leviticus 7:14', 'Leviticus', 7, 14, 'د هر ډول ډوډۍ څخه دې یوه یوه ډوډۍ د یوې ځانګړې اعانې په توګه څښتن ته وړاندې کړي. دا د هغه کاهن دپاره دي چې د حیوان وینه اخلي او د قربانۍ په ځای باندې یې شیندي.', 'د هر دول دودی چخه دې یوه یوه دودی د یوې جانګرې اعانې په توګه چشتن ته وراندې کری. دا د هغه کاهن دپاره دی چې د حیوان وینه اخلی او د قربانی په جای باندې یې شیندی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_7_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39038, 'Leviticus 7:15', 'Leviticus', 7, 15, 'د دغې سلامتۍ نذرانې د حیوان غوښه باید په هماغه ورځ چې هغه قرباني کیږي، وخوړل شي. د هغې څخه دې تر بل سهاره پورې هېڅ شی پاتې نه شي.', 'د دغې سلامتی نذرانې د حیوان غوشه باید په هماغه ورج چې هغه قربانی کیزی، وخورل شی. د هغې چخه دې تر بل سهاره پورې هېچ شی پاتې نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_7_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(39039, 'Leviticus 7:16', 'Leviticus', 7, 16, 'که چېرې یو کس د خپلې خوښې نذرانه یا د نذر ورکولو په توګه د سلامتۍ نذرانه راوړي، نو د قربانۍ غوښه دې په هماغه ورځ چې وړاندې کیږي، وخوړل شي. خو څه چې پاتې شي، هغه دې په راتلونکې ورځ وخوړل شي.', 'که چېرې یو کس د خپلې خوشې نذرانه یا د نذر ورکولو په توګه د سلامتی نذرانه راوری، نو د قربانی غوشه دې په هماغه ورج چې وراندې کیزی، وخورل شی. خو چه چې پاتې شی، هغه دې په راتلونکې ورج وخورل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_7_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39040, 'Leviticus 7:17', 'Leviticus', 7, 17, 'کومه غوښه چې د قربانۍ څخه تر درېمې ورځې پورې پاتې کیږي، باید وسوځول شي.', 'کومه غوشه چې د قربانی چخه تر درېمې ورجې پورې پاتې کیزی، باید وسوجول شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_7_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(39041, 'Leviticus 7:18', 'Leviticus', 7, 18, 'که چېرې د سلامتۍ د نذرانې کومه غوښه په درېمه ورځ وخوړل شي، خدای به د هغه کس نذرانه قبوله نه کړي. دا به د هغه په نذرانه کې حساب نه شي، بلکې هغه به ناپاکه وګڼل شي. که څوک د هغې څخه لږه وخوري، نو د خپلو بدو سزا به وویني.', 'که چېرې د سلامتی د نذرانې کومه غوشه په درېمه ورج وخورل شی، خدای به د هغه کس نذرانه قبوله نه کری. دا به د هغه په نذرانه کې حساب نه شی، بلکې هغه به ناپاکه وګنل شی. که چوک د هغې چخه لزه وخوری، نو د خپلو بدو سزا به ووینی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_7_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
